fn is_ascii_digit(c: char) -> bool {
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    s.chars().all(is_ascii_digit)
}

fn main() {
    // Example usage
    let test_char = '5';
    let test_string = String::from("12345");
    let empty_string = String::from("");

    println!("Is '{}' an ASCII digit? {}", test_char, is_ascii_digit(test_char)); // true
    println!("Are all characters in '{}' ASCII digits? {}", test_string, all_digits(test_string)); // true
    println!("Are all characters in '{}' ASCII digits? {}", empty_string, all_digits(empty_string)); // true
}